import{_ as p,a0 as l,w as d,s as i,I as s,x as t,a1 as o,A as r,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"如何在Linux下監控系統温度 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux下監控系統温度 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux下監控系統温度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux下監控系統温度 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to monitor system temperature on Linux","title":"如何在Linux下監控系統温度","tag":"201311","desc":""},"relativePath":"201311/How to monitor system temperature on Linux.md","filePath":"[post].md"}'),u={name:"201311/How to monitor system temperature on Linux.md"};function m(f,e,x,b,g,L){const n=l("Link");return d(),i("div",null,[e[21]||(e[21]=s("h1",{id:"如何在linux下監控系統温度",tabindex:"-1"},[t("如何在Linux下監控系統温度 "),s("a",{class:"header-anchor",href:"#如何在linux下監控系統温度","aria-label":"Permalink to “如何在Linux下監控系統温度”"},"​")],-1)),e[22]||(e[22]=s("p",null,"大多數情況下，你無需擔心你的電腦温度。除非製造上的缺陷，否則硬件設計一般不會使其超過最高工作温度。但即使沒有任何硬件故障，各種各樣的軟件問題也會導致硬件過熱，例如，顯卡驅動的嚴重bug，風扇控制程序的錯誤配置，CPU調頻守護進程的故障，等等。",-1)),e[23]||(e[23]=s("p",null,"嚴重的過熱可能會對硬件造成永久性的傷害，所以應當時刻小心繫統上的任何過熱問題。因此，如果有合適的温度監控系統，能在系統温度突然急速上升時，第一時間向用户發出警報，豈不美哉？",-1)),e[24]||(e[24]=s("p",null,[t("本教程，我將描述"),s("strong",null,"如何在Linux下監控系統温度"),t("。")],-1)),e[25]||(e[25]=s("p",null,"在Linux下有許多用户級工具可以檢查和監控各種系統組件的温度。",-1)),s("p",null,[e[4]||(e[4]=t("例如",-1)),o(n,{href:"http://lm-sensors.org/"},{default:r(()=>[...e[0]||(e[0]=[t("lm-sensors",-1)])]),_:1}),e[5]||(e[5]=t("，它可以從硬件嵌入式傳感器獲取信息,以達到監測温度、電壓、濕度和風扇的作用；還有",-1)),o(n,{href:"http://www.guzu.net/linux/hddtemp.php"},{default:r(()=>[...e[1]||(e[1]=[t("hddtemp",-1)])]),_:1}),e[6]||(e[6]=t(",它可以通過讀取",-1)),o(n,{href:"http://en.wikipedia.org/wiki/S.M.A.R.T."},{default:r(()=>[...e[2]||(e[2]=[t("S.M.A.R.T.",-1)])]),_:1}),e[7]||(e[7]=t("參數來測量温度；今天我們要介紹的是",-1)),o(n,{href:"http://wpitchoune.net/blog/psensor/"},{default:r(()=>[...e[3]||(e[3]=[t("psensor",-1)])]),_:1}),e[8]||(e[8]=t("，這是一款前端圖形化界面温度監測工具，能夠可視化顯示CPU、Nvidia/ATI/AMD各家顯卡以及硬盤等多個硬件設備的温度。",-1))]),e[26]||(e[26]=a(`<p>接下來，我將描述如何設置psensor來監控CPUs和硬盤的温度。</p><h3 id="在linux-桌面系統中安裝-psensor" tabindex="-1">在Linux 桌面系統中安裝 psensor### <a class="header-anchor" href="#在linux-桌面系統中安裝-psensor" aria-label="Permalink to “在Linux 桌面系統中安裝 psensor###”">​</a></h3><p>使用psensor可視化顯示系統温度，需要基於其他工具諸如lm-sensors和hddtemp等獲得的數據。因此你需要在安裝psensor的同時，一併安裝這兩款工具。</p><p>在Debian或Ubuntu下安裝psensor:</p><pre><code>$ sudo apt-get install lm-sensors hddtemp psensor
</code></pre><p>在Ubuntu下還可以通過PPA倉庫安裝最新版本的psensor：</p><pre><code>$ sudo add-apt-repository ppa:jfi/ppa
$ sudo apt-get update
$ sudo apt-get install lm-sensors hddtemp psensor
</code></pre><p>在Fedora下安裝psensor：</p><pre><code>$ sudo yum install lm_sensors hddtemp
$ sudo yum install gcc gtk3-devel GConf2-devel lm_sensors-devel cppcheck libatasmart-devel libcurl-devel json-c-devel libmicrohttpd-devel help2man libnotify-devel libgtop2-devel make
$ wget http://wpitchoune.net/psensor/files/psensor-0.8.0.3.tar.gz
$ tar xvfvz psensor-0.8.0.3.tar.gz
$ cd psensor-0.8.0.3
$ ./configure
$ make
$ sudo make install 
</code></pre><p>這裏注意，由於需要GTK3庫的支持，psensor無法與搭載GNOME2桌面的CentOs或RHEL 6兼容。</p><h3 id="在linux中配置-psensor" tabindex="-1">在Linux中配置 psensor <a class="header-anchor" href="#在linux中配置-psensor" aria-label="Permalink to “在Linux中配置 psensor”">​</a></h3><p>在啓動 psensor之前，你需要先配置lm_sensors和hddtemp。</p><h4 id="lm-sensors-配置" tabindex="-1">lm_sensors 配置 <a class="header-anchor" href="#lm-sensors-配置" aria-label="Permalink to “lm_sensors 配置”">​</a></h4><p>運行以下命令，配置lm_sensors，每一項都選擇YES。</p><pre><code>$ sudo sensors-detect 
</code></pre><p>這個命令將會探查和檢測你硬件中嵌入的傳感器(包括CPUs、儲存控制器、I/O芯片)，然後自動決定系統中哪個驅動模組需要載入並監測其温度。</p><p>一旦傳感器檢測完成，你需要把檢測到的驅動模組添加到/etc配置中，這樣它們才可以在開機時自動加載。</p><p><img src="http://farm6.staticflickr.com/5476/10719567256_029533a588_z.jpg" alt="img"></p><p>在Debian或Ubuntu下，檢測到的驅動模組將會被添加到/etc/modules。在Fedora下，驅動信息會添加到/etc/sysconfig/lm_sersors。</p><p>接下來，繼續加載必要的模組，如下:</p><p>Ubuntu:</p><pre><code>$ sudo service module-init-tools start 
</code></pre><p>Debian:</p><pre><code>$ sudo /etc/init.d/kmod start
</code></pre><p>Fedora</p><pre><code>$ sudo service lm_sensors start 
</code></pre><h4 id="hddtemp-配置" tabindex="-1">hddtemp 配置 <a class="header-anchor" href="#hddtemp-配置" aria-label="Permalink to “hddtemp 配置”">​</a></h4><p>你還需要啓動hddtemp，監控硬盤驅動器的温度。</p><p>運行下列命令，作為一個守護進程啓動hddtemp。記得把“/dev/sda”替換成你係統上的硬盤驅動器。</p><pre><code>$ sudo hddtemp -d /dev/sda 
</code></pre><h3 id="用-psensor-監控系統温度" tabindex="-1">用 psensor 監控系統温度 <a class="header-anchor" href="#用-psensor-監控系統温度" aria-label="Permalink to “用 psensor 監控系統温度”">​</a></h3><p>要啓動psensor監測温度，只需簡單運行:</p><pre><code>$ psensor 
</code></pre><p>psensor窗口將顯示一個可用的傳感器列表，並將傳感器中讀出的温度可視化顯示出來。你可以選擇性地啓用或禁用任意一個傳感器。</p>`,34)),s("p",null,[o(n,{href:"http://www.flickr.com/photos/xmodulo/10719475225/"},{default:r(()=>[...e[9]||(e[9]=[s("img",{src:"http://farm8.staticflickr.com/7448/10719475225_f89b6f7191_z.jpg",alt:""},null,-1)])]),_:1})]),e[27]||(e[27]=s("p",null,"另外，你可以為每個傳感器設置警報級別，這樣當傳感器温度超過某一閾值時，你就能得到通知了。",-1)),e[28]||(e[28]=s("p",null,[s("img",{src:"http://farm6.staticflickr.com/5534/10719755343_ba143454af_z.jpg",alt:"img"})],-1)),e[29]||(e[29]=s("p",null,"psensor默認使用的温度單位是“攝氏度”，最新的版本（0.7-0.8）支持在攝氏與華氏之間轉換温度單位，如果你用的版本比較舊（例如0.6.x）並且不支持温度單位轉換，Ubuntu用户可以通過PPA倉庫來安裝最新版的psensor，Debian用户則可以通過源代碼來安裝。",-1)),e[30]||(e[30]=s("hr",null,null,-1)),s("p",null,[e[11]||(e[11]=t("via: ",-1)),o(n,{href:"http://xmodulo.com/2013/11/monitor-system-temperature-linux.html"},{default:r(()=>[...e[10]||(e[10]=[t("http://xmodulo.com/2013/11/monitor-system-temperature-linux.html",-1)])]),_:1})]),s("p",null,[e[14]||(e[14]=t("譯者：",-1)),o(n,{href:"https://github.com/Luoxcat"},{default:r(()=>[...e[12]||(e[12]=[t("Luoxcat",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),o(n,{href:"http://blog.csdn.net/tinyeyeser"},{default:r(()=>[...e[13]||(e[13]=[t("Mr小眼兒",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const C=p(u,[["render",m]]);export{k as __pageData,C as default};
